class CTriangle:public CPolygon
{
public:
    CTriangle(int sides[]);
    double getArea();
private:
    int sides[3];
};
CTriangle::CTriangle(int sides[])
{
    for(int i=0;i<3;i++)
        this->sides[i] = sides[i];
}
double CTriangle::getArea()
{
    double s = 0;
    for(int i=0;i<3;i++)
        s+=sides[i];
    s/=2;
    return sqrt(s*(s-sides[0])*(s-sides[1])*(s-sides[2]));
}
